package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rate set on a sheet for each grade. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's rates by grade. */
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAsc(sheetId);
    }

    /** Set the rate for a grade, replacing the one it had. */
    @Transactional
    public Rate set(String sheetId, String user, String grade, BigDecimal rate) {
        sheets.load(sheetId);
        BigDecimal scaled = rate.setScale(2, RoundingMode.UNNECESSARY);
        Rate saved = rates.findBySheetIdAndGrade(sheetId, grade)
                .map(existing -> {
                    existing.setRate(scaled);
                    return existing;
                })
                .orElseGet(() -> new Rate(sheetId, grade, scaled));
        saved = rates.saveAndFlush(saved);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                + " rate=" + saved.getRate().toPlainString());
        return saved;
    }
}
-- A sheet's rate for a grade: a percent with two decimals (0.00 or more). A grade has at most one
-- rate on a sheet; a grade with no rate has none, and its claims' due is n/a.
CREATE TABLE rate (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    grade CHAR(1) NOT NULL,
    rate DECIMAL(7, 2) NOT NULL CHECK (rate >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- A claim's due fixed when it is settled: the amount times its person's grade rate at that moment,
-- kept as it was whatever the rates do later. Null for a claim not settled, or settled while the
-- grade had no rate.
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(12, 2);

